const OG_TESTTAB_CATEGORIES: [(&str, &str); 18] = [
    ("buttons", "Buttons"),
    ("toggles", "Toggles"),
    ("tabs", "Tabs"),
    ("inputs", "Inputs"),
    ("cards", "Cards"),
    ("badges", "Badges"),
    ("checkboxes", "Checkboxes"),
    ("utilities", "Utilities"),
    ("calendar-time", "Calendar & Time"),
    ("row-info-tile", "Row Info Tile"),
    ("dropdowns", "Dropdowns"),
    ("slider", "Slider"),
    ("textbox", "Text Box"),
    ("upload-components", "Upload Components"),
    ("progress-bar", "Progress Bar"),
    ("table", "Table"),
    ("collapsible", "Collapsible"),
    ("modals", "Modals"),
];

fn render_category_chip_grid() -> String {
    OG_TESTTAB_CATEGORIES
        .iter()
        .enumerate()
        .map(|(index, (id, title))| {
            format!(
                r#"<button type="button" class="ui-tab {active}" data-tab-id="{id}" data-category-chip="{id}" aria-selected="{selected}" data-depth="3"><span class="ui-tab__content"><span class="ui-tab__label">{title}</span></span></button>"#,
                active = if index == 0 { "ui-tab--active active" } else { "" },
                selected = if index == 0 { "true" } else { "false" },
                id = id,
                title = title
            )
        })
        .collect::<Vec<_>>()
        .join("")
}

fn section(id: &str, title: &str, body: &str, active: bool) -> String {
    format!(
        r#"<section id="showcase-{id}" class="showcase-section {active}" data-tab-panel="{id}" data-og-category-section="{id}"><h3>{title}</h3>{body}</section>"#,
        id = id,
        title = title,
        active = if active { "active" } else { "" },
        body = body
    )
}

