fn render_test_showcase() -> String {
    format!(
        r#"<section class="pane" id="pane-test" data-pane-panel="test" data-view-panel="test" role="tabpanel" aria-label="Test"><div class="test-tablet" data-tab-scope="test" data-native-stock-test="true" data-admin-viewport="test" data-react-quarry="legacy-tabs/testTab" data-ux-library="og-styles-common-ui" data-ux-registry="og-test-bedrock"><div class="ui-tab-group" role="tablist" aria-label="Test sections"><button type="button" class="ui-tab ui-tab--active active" data-tab-id="showcase" aria-selected="true" data-depth="2"><span class="ui-tab__content"><span class="ui-tab__label">Component Showcase</span></span></button><button type="button" class="ui-tab" data-tab-id="services" aria-selected="false" data-depth="2"><span class="ui-tab__content"><span class="ui-tab__label">Services</span></span></button><button type="button" class="ui-tab" data-tab-id="config" aria-selected="false" data-depth="2"><span class="ui-tab__content"><span class="ui-tab__label">Configuration</span></span></button><button type="button" class="ui-tab" data-tab-id="health" aria-selected="false" data-depth="2"><span class="ui-tab__content"><span class="ui-tab__label">Health Status</span></span></button></div><div class="test-tablet-content">{showcase}{services}{config}{health}</div></div></section>"#,
        showcase = render_component_showcase(),
        services = render_test_services(),
        config = render_test_config(),
        health = render_test_health()
    )
}
